import{_ as t,o as r,c as s,a2 as p}from"./chunks/framework.B2QVIpOM.js";const h=JSON.parse('{"title":"汉华中学 · 2026年资料 · 中四 · 考试与面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-42659f42","school_zh":"汉华中学","school_en":"—","grade":"s4","year":"2026-source","year_label":"2026年资料","type":"mixed","title":"汉华中学 · 2026年资料 · 中四 · 考试与面试","anonymous":true,"source_ids":["HONWA-S4-202606","LS0211"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/school-42659f42/s4/2026-source-mixed.md","filePath":"reports/school-42659f42/s4/2026-source-mixed.md"}'),e={name:"reports/school-42659f42/s4/2026-source-mixed.md"};function n(a,o,g,c,l,u){return r(),s("div",null,[...o[0]||(o[0]=[p('<h1 id="汉华中学-·-2026年资料-·-中四-·-考试与面试" tabindex="-1">汉华中学 · 2026年资料 · 中四 · 考试与面试 <a class="header-anchor" href="#汉华中学-·-2026年资料-·-中四-·-考试与面试" aria-label="Permalink to &quot;汉华中学 · 2026年资料 · 中四 · 考试与面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-42659f42">← 返回汉华中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-honwa-s4-202606" tabindex="-1">资料来源：汉华小学插班小四考情&amp;面经_2026年秋季.pdf <a class="header-anchor" href="#record-honwa-s4-202606" aria-label="Permalink to &quot;资料来源：汉华小学插班小四考情&amp;amp;面经_2026年秋季.pdf {#record-honwa-s4-202606}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生／家长反馈整理</p><p><strong>入学途径：</strong> 插班</p><p><strong>课程分支：</strong> 课程分支未注明</p><p><strong>反馈时间：</strong> 2026年6月</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 各科分别注明</p><p><strong>笔试期间穿插面试</strong></p><p>考生在笔试中途被叫去面试，之后回去继续答卷。原反馈称总时长三小时15分钟，但同时写出的起止钟点与此不符，实际总时长未能确定。</p><p><strong>考场环境</strong></p><p>考生觉得广播及面试叫号分散注意力，冷气较强，也影响了当时状态。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，口语未注明</p><p><strong>阅读理解</strong></p><p>篇目为史铁生《玩具》：回忆母亲带自己到北海买玩具车，童年印象中老屋台阶很高，长大后重访发现其实很矮。文章由记忆与眼前景象的差别，引出对真实及生命经验变化的思考。</p><p><strong>材料作文</strong></p><p>两人分别主张学生应跟随老师扎实学习课内基础，或突破尝试不同内容、接触社会以获得经验与技能。结合对话，以“本分守己”或“勇于突破”为题，写至少450字。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>分值与题型</strong></p><p>共65分：甲部15道选择题，占30分；乙部四道大题，占35分。</p><p><strong>考点与作答感受</strong></p><p>包含因式分解、一次函数及立体几何。考生对某道因式分解题仍有疑问，未保留足够题干以核实；认为一次函数需要运算熟练度，立体几何思路虽不复杂但数据大、计算较繁。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>阅读及写作</strong></p><p>包含英语阅读及写作，具体题目没有保留；考生认为有一定难度。</p></blockquote><blockquote><p><strong>学生面试：</strong> 语言未注明</p><p><strong>考生向学校提问</strong></p><p>老师多次邀请考生提出问题。考生询问乐团是否有长笛位置，得到有名额的答复；又根据校训“汉粹国菁”询问重视中文教育是否影响英文科的比重。</p><p><strong>面试后的用时</strong></p><p>考生认为交流尚可，但面试结束时笔试临近结束，需要回去赶写试卷。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>数学的个人难度排序</strong></p><p>宁波公学＞汉华中学≥黄棣珊纪念中学＞港九潮州公会中学＞创知中学。</p><p><strong>英语的个人难度排序</strong></p><p>阅读方面，该生认为汉华最难，其次宁波，再到港九潮州公会、黄棣珊及创知；写作方面认为黄棣珊最难，港九潮州公会不低于宁波，其后是汉华及创知。这是同一考生跨校比较，不代表统一难度评级。</p></blockquote><h2 id="record-ls0211" tabindex="-1">资料来源：汉华中学插班中四考情_2026年秋季.jpg <a class="header-anchor" href="#record-ls0211" aria-label="Permalink to &quot;资料来源：汉华中学插班中四考情_2026年秋季.jpg {#record-ls0211}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生／家长反馈整理</p><p><strong>入学途径：</strong> 插班</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文（简繁未注明）</p><p><strong>写作</strong></p><p>包含一篇小作文。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>题型与难度反馈</strong></p><p>包含一篇小作文。考生认为英语难度较高，比上一周参加的马鞍山崇真中学考试更难。</p></blockquote><blockquote><p><strong>综合面试：</strong> 普通话或粤语</p><p><strong>面试穿插安排</strong></p><p>笔试进行期间，考生被叫出考场参加约15分钟的面试；没有英文面试环节。</p><p><strong>题目回忆</strong></p><p>家长认为问题与此前教师讲解过的内容相近，但没有提供具体题目。</p></blockquote><blockquote><p><strong>整体反馈：</strong></p><p><strong>难度与人数观察</strong></p><p>家长认为本次考试整体较难，观察到中四考生人数与上一周马鞍山崇真的场次相近，参加两校后感受到插班竞争。</p><p><strong>家长对轮次的推测</strong></p><p>家长推测难度较高可能与“只有一轮、需要拉开差距”有关；这是个人推测，未据此确定实际轮次。</p></blockquote>',24)])])}const i=t(e,[["render",n]]);export{h as __pageData,i as default};
